# -*- coding: utf-8 -*-
import json, sys
from gen3 import *  # noqa
from gen1 import OUT, ep, FILES, REPORT, _validate_field, _script_items, _check_source

FIELD_MAP = {"request": "request", "responses": "responses", "rules": "business_rules"}
bad = 0
for key, fields in OUT.items():
    method, path = key.split(" ", 1)
    e = ep(method, path)
    for local_name, value in fields.items():
        field = FIELD_MAP[local_name]
        errors = []
        shared_ids = set()
        _validate_field(FILES, field, value, f"{key}.{field}", errors, shared_ids)
        existing = set(_script_items(field, e.get(field)))
        for canon in _script_items(field, value):
            if canon not in existing:
                errors.append("script item not identical: " + canon[:160])
        if errors:
            bad += 1
            print("!!", key, field)
            for x in errors:
                print("   ", x)
print("payloads:", len(OUT), "errors:", bad)

# emit compact json per call
out = {}
for key, fields in OUT.items():
    method, path = key.split(" ", 1)
    for local_name, value in fields.items():
        out[f"{key}||{FIELD_MAP[local_name]}"] = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
open("payloads.json", "w", encoding="utf-8").write(json.dumps(out, ensure_ascii=False))
print("wrote payloads.json", len(out))

